            report=new JSONObject();String mode=args.getString("mode","web");
            activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));
            waitForIdleSync();report.put("mode",mode);
            switch(mode){case "catalog","catalogDownload"->catalog();case "history"->history();case "tapProbe12"->tapProbe12();case "ui12"->ui12();case "restoreProgress"->restoreProgress();case "liveRevision"->liveRevision();case "correct"->correct();case "revision"->revision();case "layout"->layout();case "inspect"->inspect();case "web"->web();case "download"->download();case "toolbar"->toolbar();case "vk"->vk();case "local"->local();case "reader"->reader();case "folder"->folder();case "saf"->saf();case "fixture"->fixture();case "transfers"->transfers();case "finish"->cleanupAndVerify();default->throw new Exception("Unknown test mode");}
