        MotionEvent up=MotionEvent.obtain(now,SystemClock.uptimeMillis(),MotionEvent.ACTION_UP,x,v.getHeight()*.1f,0);runOnMainSync(()->v.dispatchTouchEvent(up));up.recycle();Thread.sleep(800);
