        pinch(r);
        final float[] zoom=new float[1];runOnMainSync(()->zoom[0]=findPage(r.getWindow().getDecorView()).testZoom());report.put("zoomFactor",zoom[0]);report.put("scaleGestureDelivered",true);if(zoom[0]<=1.1)throw new Exception("Pinch did not enlarge the page");
