    private void pinch(ReaderActivity r)throws Exception{
        final ReaderActivity.PageView[] target=new ReaderActivity.PageView[1];runOnMainSync(()->target[0]=findPage(r.getWindow().getDecorView()));ReaderActivity.PageView v=target[0];long t=SystemClock.uptimeMillis();
        MotionEvent.PointerProperties[] pp={new MotionEvent.PointerProperties(),new MotionEvent.PointerProperties()};MotionEvent.PointerCoords[] pc={new MotionEvent.PointerCoords(),new MotionEvent.PointerCoords()};for(int n=0;n<2;n++){pp[n].id=n;pp[n].toolType=MotionEvent.TOOL_TYPE_FINGER;pc[n].pressure=1;pc[n].size=1;pc[n].touchMajor=20;pc[n].touchMinor=20;pc[n].x=v.getWidth()/2f+(n==0?-100:100);pc[n].y=v.getHeight()/2f;}
        readerTouch(v,t,MotionEvent.ACTION_DOWN,1,pp,pc);Thread.sleep(40);readerTouch(v,t,MotionEvent.ACTION_POINTER_DOWN|(1<<8),2,pp,pc);Thread.sleep(40);
        for(int n=1;n<=12;n++){pc[0].x=v.getWidth()/2f-100-n*35;pc[1].x=v.getWidth()/2f+100+n*35;readerTouch(v,t,MotionEvent.ACTION_MOVE,2,pp,pc);Thread.sleep(40);}
        readerTouch(v,t,MotionEvent.ACTION_POINTER_UP|(1<<8),2,pp,pc);readerTouch(v,t,MotionEvent.ACTION_UP,1,pp,pc);
    }
    private void readerTouch(ReaderActivity.PageView v,long down,int action,int count,MotionEvent.PointerProperties[] pp,MotionEvent.PointerCoords[] pc){MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,count,pp,pc,0,0,1,1,0,0,InputDevice.SOURCE_TOUCHSCREEN,0);runOnMainSync(()->v.dispatchTouchEvent(e));e.recycle();}
    private void saf()throws Exception{
        android.content.SharedPreferences pref=activity.getSharedPreferences("settings",0);String before=pref.getString("tree","");Uri tree=null;Store.Item local=null;
        try {
            Intent picker=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION).putExtra(android.provider.DocumentsContract.EXTRA_INITIAL_URI,Uri.parse("content://com.android.externalstorage.documents/document/primary%3ADownload%2FMagazine%20Library%20Test"));
            runOnMainSync(()->activity.startActivityForResult(picker,10));Thread.sleep(2000);
            android.view.accessibility.AccessibilityNodeInfo button=null;for(int n=0;n<10;n++){button=node(getUiAutomation().getRootInActiveWindow(),new String[]{"使用此文件夹","使用这个文件夹","使用该文件夹","USE THIS FOLDER","Use this folder"});if(button!=null)break;Thread.sleep(1000);}org.json.JSONArray pickerButtons=new org.json.JSONArray();controls(getUiAutomation().getRootInActiveWindow(),pickerButtons);report.put("pickerControls",pickerButtons);if(button==null)throw new Exception("Folder selection button not found");button.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK);Thread.sleep(700);
            android.view.accessibility.AccessibilityNodeInfo allow=node(getUiAutomation().getRootInActiveWindow(),new String[]{"允许","ALLOW","Allow"});if(allow!=null)allow.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK);Thread.sleep(500);
            String chosen=pref.getString("tree","");report.put("chosenTree",Uri.decode(chosen));if(!Uri.decode(chosen).endsWith("Download/Magazine Library Test"))throw new Exception("The isolated test folder was not selected");tree=Uri.parse(chosen);
            Store.Item sample=Store.get(getTargetContext()).item(8);if(sample==null||!Store.READY.equals(sample.status))throw new Exception("Sample PDF missing");local=Store.get(getTargetContext()).add("","","Directory Fixture – October 2026",chosen,"");File f=Files.part(getTargetContext(),local.id);
            try(InputStream in=getTargetContext().getContentResolver().openInputStream(Uri.parse(sample.uri));OutputStream out=new FileOutputStream(f)){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}int pages=Files.validate(f);Uri saved=Files.publish(getTargetContext(),local,f);report.put("savedUri",Uri.decode(saved.toString()));report.put("pages",pages);
            try(ParcelFileDescriptor fd=getTargetContext().getContentResolver().openFileDescriptor(saved,"r");PdfRenderer p=new PdfRenderer(fd)){if(p.getPageCount()!=pages)throw new Exception("Saved PDF differs");report.put("savedPdfReadable",true);}
            android.provider.DocumentsContract.deleteDocument(getTargetContext().getContentResolver(),saved);f.delete();
        } finally {
            if(local!=null)Store.get(getTargetContext()).getWritableDatabase().delete("items","id=?",new String[]{""+local.id});pref.edit().putString("tree",before).apply();if(tree!=null)getTargetContext().getContentResolver().releasePersistableUriPermission(tree,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);
        }
    }
    private android.view.accessibility.AccessibilityNodeInfo node(android.view.accessibility.AccessibilityNodeInfo root,String[] names){if(root==null)return null;for(String name:names)if(!root.isEditable()&&(name.contentEquals(root.getText()==null?"":root.getText())||name.contentEquals(root.getContentDescription()==null?"":root.getContentDescription())))return root;for(int n=0;n<root.getChildCount();n++){android.view.accessibility.AccessibilityNodeInfo found=node(root.getChild(n),names);if(found!=null)return found;}return null;}
    private void controls(android.view.accessibility.AccessibilityNodeInfo root,org.json.JSONArray out)throws Exception{if(root==null)return;String id=root.getViewIdResourceName(),cls=String.valueOf(root.getClassName());if(cls.contains("Button")||(id!=null&&id.contains("action"))){org.json.JSONObject o=new org.json.JSONObject();o.put("text",root.getText());o.put("description",root.getContentDescription());o.put("id",id);o.put("enabled",root.isEnabled());out.put(o);}for(int n=0;n<root.getChildCount();n++)controls(root.getChild(n),out);}
    private void fixture()throws Exception{
        String url=args.getString("url"),title=args.getString("title","Test Issue – October 2026");if(url==null)throw new Exception("Fixture url required");
        runOnMainSync(()->{activity.getSharedPreferences("settings",0).edit().putBoolean("askedNotify",true).apply();activity.enqueue(url,title,MainActivity.HOME,activity.testWeb().getSettings().getUserAgentString());activity.showTab("downloads");});
        Store.Item i=Store.get(getTargetContext()).all().stream().filter(x->x.url.equals(url)).findFirst().orElseThrow();i=awaitEnd(i.id,45);itemReport(i);if(args.getString("expected","ready").equals(i.status)){if(Store.READY.equals(i.status))checkPdf(i);}else throw new Exception("Unexpected fixture state "+i.status);
    }
    private void transfers()throws Exception{
        try(TestTlsServer server=new TestTlsServer(getContext())) {
            CompletableFuture<Boolean> cookie=new CompletableFuture<>();runOnMainSync(()->android.webkit.CookieManager.getInstance().setCookie(server.url("/"),"fixtureSession=authorized; Path=/; Secure",cookie::complete));if(!cookie.get(5,TimeUnit.SECONDS))throw new Exception("Fixture cookie failed");
            Store.Item redirect=task(server.url("/redirect"),"Transfer Test – October 2026");redirect=awaitEnd(redirect.id,15);assertReady(redirect);report.put("redirectDownload",true);report.put("cookieForwarded",server.cookieSeen);if(!server.cookieSeen)throw new Exception("Session cookie missing");report.put("redirectCookieApplied",server.secondCookieSeen);if(!server.secondCookieSeen)throw new Exception("Redirect response cookie missing");
            Store.Item slow=task(server.url("/slow"),"Resume Test – October 2026");for(int n=0;n<60;n++){if(Files.part(getTargetContext(),slow.id).length()>0)break;Thread.sleep(100);}Store.get(getTargetContext()).status(slow.id,Store.PAUSED,"");slow=awaitEnd(slow.id,10);long partial=Files.part(getTargetContext(),slow.id).length();if(partial<1||partial>=server.pdf.length)throw new Exception("Pause did not retain partial bytes");report.put("pausedBytes",partial);
            for(int n=0;n<50&&DownloadService.isAlive;n++)Thread.sleep(100);
            long resumeId=slow.id;runOnMainSync(()->{Store.get(getTargetContext()).status(resumeId,Store.QUEUED,"");DownloadService.start(activity);activity.moveTaskToBack(true);});slow=awaitEnd(slow.id,25);assertReady(slow);report.put("backgroundResume",true);report.put("rangeUsed",server.rangeSeen);if(!server.rangeSeen)throw new Exception("Range resume was not used");
            runOnMainSync(()->{for(ActivityManager.AppTask t:activity.getSystemService(ActivityManager.class).getAppTasks())t.moveToFront();});Thread.sleep(400);
            Store.Item auth=task(server.url("/auth"),"Auth Test – October 2026");auth=awaitEnd(auth.id,10);if(!Store.AUTH.equals(auth.status)||!auth.uri.isEmpty())throw new Exception("Challenge was stored as a PDF");report.put("challengeNotPublished",true);
            Store.Item html=task(server.url("/html"),"HTML Test – October 2026");html=awaitEnd(html.id,10);if(!Store.WAITING.equals(html.status)||!html.uri.isEmpty())throw new Exception("HTML was stored as PDF");report.put("htmlNotPublished",true);
            Store.Item cross=task(server.url("/cross"),"Isolation Test – October 2026");cross=awaitEnd(cross.id,10);assertReady(cross);if(server.cookieLeaked)throw new Exception("Cookie crossed host boundary");report.put("crossHostCookiesIsolated",true);
            runOnMainSync(()->activity.showTab("downloads"));
            // Remove only IDs created by this test; no user-selected files or real magazines.
            for(Store.Item i:new Store.Item[]{redirect,slow,auth,html,cross}){if(!i.uri.isEmpty())getTargetContext().getContentResolver().delete(Uri.parse(i.uri),null,null);Files.part(getTargetContext(),i.id).delete();Files.cover(getTargetContext(),i.id).delete();Store.get(getTargetContext()).getWritableDatabase().delete("items","id=?",new String[]{""+i.id});}
        }
    }
    private Store.Item task(String url,String title)throws Exception{runOnMainSync(()->activity.enqueue(url,title,MainActivity.HOME,activity.testWeb().getSettings().getUserAgentString()));return Store.get(getTargetContext()).all().stream().filter(i->url.equals(i.url)).findFirst().orElseThrow();}
